#include <iostream>
#include <vector>

using namespace std;

/**
 * Problem: 10607 - Joseph's Cousin
 * 
 * 解題思路：
 * 1. 這是約瑟夫問題的變體，每次剔除人的間距是質數序列。
 * 2. 使用約瑟夫問題的動態規劃遞迴公式：
 *    f(n, k) = (f(n-1, k) + m) % n
 *    但在這裡 m 是變動的。設 f(i) 為剩下 i 個人時的倖存者位置。
 * 3. 遞迴關係：f(i) = (f(i-1) + prime[n-i]) % i，其中 f(1) = 0。
 * 4. 注意質數序列的順序。當剩 i 個人時，我們剛剔除了第 n-i 個人，使用的是第 n-i+1 個質數。
 */

const int MAX_N = 3501;
int primes[MAX_N];

void sieve() {
    vector<bool> is_prime(40000, true);
    is_prime[0] = is_prime[1] = false;
    int count = 0;
    for (int p = 2; count < MAX_N; ++p) {
        if (is_prime[p]) {
            primes[count++] = p;
            for (int i = p * p; i < 40000; i += p) is_prime[i] = false;
        }
    }
}

int main() {
    sieve();
    int n;
    while (cin >> n && n != 0) {
        int res = 0; // f(1) = 0
        for (int i = 2; i <= n; ++i) {
            // 當剩下 i 個人時，使用的是第 n-i+1 個質數 (索引為 n-i)
            res = (res + primes[n - i]) % i;
        }
        cout << res + 1 << endl;
    }
    return 0;
}
